// === data.json ===
{ "toko": "Kopi Rina", "menu": ["Kopi Susu", "Teh Tarik"] }
// === stok.js ===
let jumlah = 10;
exports.ambil = (n) => {
  jumlah -= n;
  return jumlah;
};
exports.sisa = () => jumlah;
// === main.js ===
const data = require('./data.json');
const stok = require('./stok.js');
console.log(data.toko, data.menu.length);
stok.ambil(3);
console.log(stok.sisa());
console.log(require('./stok.js') === stok);
console.log(typeof __dirname, typeof require);

langkah.jawaban:
// === kasir.js ===
function hitung(harga, jumlah) {
  return harga * jumlah;
}
module.exports = { hitung };
// === main.js ===
const { hitung } = require('./kasir.js');
console.log('Kopi Susu x2:', hitung(18000, 2));

// === kasir.js ===
function hitung(harga, jumlah) {
  return harga * jumlah;
}
function diskon(total, persen) {
  return total - (total * persen) / 100;
}
module.exports = { hitung, diskon };
// === main.js ===
const { hitung, diskon } = require('./kasir.js');
console.log('Kopi Susu x2:', hitung(18000, 2));
console.log('Setelah diskon:', diskon(hitung(18000, 2), 10));

