function luas(p, l) {
  return p * l;
}
module.exports = { luas };
// === main.js ===
const { luas } = require('./alat.js');
console.log(luas(10, 5));
console.log('masih CommonJS');

cards.solution:
// === alat.js ===
export function luas(p, l) {
  return p * l;
}
// === main.js ===
import { luas } from './alat.js';
console.log(luas(10, 5));
